import { afterEach, describe, expect, it, vi } from "vitest";
import { audioPacket, makePipelinePlayer } from "../helpers/pipeline-player";

// dist/wasm/movi.js is generated by build:wasm and absent in the unit-test
// job; MoviPlayer's module graph imports it eagerly, so stub the module the
// same way the other MoviPlayer-importing suites (rebuffer-unlock.test.ts,
// video-worker-policy.test.ts) already do.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));
vi.mock("dashjs", () => ({ MediaPlayer: vi.fn() }));
vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: { isBrowserSupported: vi.fn(() => false) },
    polyfill: { installAll: vi.fn() },
    net: { NetworkingEngine: { RequestType: { LICENSE: 1 } } },
  },
}));

afterEach(() => {
  vi.unstubAllGlobals();
});

/**
 * P4 — `maxAudioBuffered = (isAudioSoftware ? 5.0 : ...) * rateScale`, where
 * `rateScale = rate < 1.0 ? 1.0 / rate : Math.min(2.0, rate)` (MoviPlayer.ts,
 * the "P4 — recomputed for the post-A5 architecture" block). Since A5 made
 * `needsSoftwareDecoding()` unconditional, isAudioSoftware is true for every
 * audio track now, so the base is always 5.0s and rate is the only variable
 * left — these tests pin the boundary at each rate regime docs/PLAN_MERGE.MD
 * calls out (1x, slow, fast-capped).
 *
 * The cushion used to gate `demuxer.readPacket()` for both streams; since the
 * pull pipeline (docs/PLAN_MOVI_PIPELINE.md P1) it gates only whether queued
 * audio is fed to the decoder. A player mid-playback (not rebuffering, not
 * seeking) with one audio packet queued and the video side idle.
 */
describe("MoviPlayer P4: maxAudioBuffered feed boundary", () => {
  async function feedsAudio(rate: number, audioBuffered: number) {
    const f = await makePipelinePlayer({
      audioBuffered,
      rendererQueue: 30,
      queuedAudio: [audioPacket(12)],
    });
    f.player.clock.setPlaybackRate(rate);
    await f.tick();
    return f.audioDecode.mock.calls.length > 0;
  }

  it("at 1x, feeds while the audio cushion sits just under the 5.0s target", async () => {
    expect(await feedsAudio(1.0, 4.99)).toBe(true);
  }, 20_000);

  it("at 1x, holds audio in its queue once the cushion clears the 5.0s target", async () => {
    expect(await feedsAudio(1.0, 5.01)).toBe(false);
  }, 20_000);

  it("at 0.5x, the target doubles to 10.0s (rateScale = 1/rate)", async () => {
    expect(await feedsAudio(0.5, 9.99)).toBe(true);
    expect(await feedsAudio(0.5, 10.01)).toBe(false);
  }, 20_000);

  it("at 1.5x, the target scales proportionally to 7.5s (rateScale = rate, uncapped below 2x)", async () => {
    expect(await feedsAudio(1.5, 7.49)).toBe(true);
    expect(await feedsAudio(1.5, 7.51)).toBe(false);
  }, 20_000);

  it("at 4x, rateScale is capped at 2.0 (target stays 10.0s, not 20.0s)", async () => {
    expect(await feedsAudio(4.0, 9.99)).toBe(true);
    expect(await feedsAudio(4.0, 10.01)).toBe(false);
  }, 20_000);
});
